    # Lap(b) = scale * sign(u) * ln(1 - 2|u|), where u ~ Uniform(-0.5, 0.5)
    sensitivity = 1.0
    scale = sensitivity / epsilon

    results = {}
    for key in ["A", "B", "C"]:
        u = rng.random() - 0.5
        noise = -scale * numpy.sign(u) * math.log(1 - 2 * abs(u))
        results[key] = float(bins[key]) + noise

    return results

