def private_argmax(data, epsilon, rng):
    categories = ["A", "B", "C", "D"]
    counts = {cat: 0 for cat in categories}
    for item in data:
        if item in counts:
            counts[item] += 1

    # Sensitivity for counting queries is 1 (adding/removing one record
    # changes one count by at most 1).
    # For Report Noisy Max, we add Gumbel(1/epsilon) noise to each count.
    # Gumbel(scale) is generated by -scale * log(-log(uniform(0, 1))).

    noisy_counts = {}
    for cat in categories:
        u = rng.random()
        # Ensure u is in (0, 1) to avoid log(0)
        while u == 0:
            u = rng.random()
        noise = -(1.0 / epsilon) * math.log(-math.log(u))
        noisy_counts[cat] = counts[cat] + noise

    # Return the category with the maximum noisy count.
    # In case of ties, argmax will pick the first occurrence, 
    # which is consistent with the definition of the mechanism.
    best_cat = categories[0]
    max_val = noisy_counts[categories[0]]
    for cat in categories[1:]:
        if noisy_counts[cat] > max_val:
            max_val = noisy_counts[cat]
            best_cat = cat

    return best_cat

